package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LedgerRec struct {
	BrBranch string
	BrAcct   string
	BrType   string
	BrAmt    decimal.Decimal
}

var WsEofFlag string
var WsFirstFlag string
var WsPrevBranch string
var WsPrevAcct string
var WsBal decimal.Decimal
var WsBranchTot decimal.Decimal
var WsGrandTot decimal.Decimal
var WsSkipped int64
var WsAmtEd string
var WsBalEd string
var WsTotEd string

var ledgerRec LedgerRec

var inputLines []string
var inputIdx int

func isInputDone() bool { return WsEofFlag == "Y" }
func isFirstRecord() bool { return WsFirstFlag == "Y" }

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func formatEdited(val decimal.Decimal, picture string) string {
	// picture may contain '-', 'Z', '9', ',', '.'
	// Use absolute value for digit extraction, sign handled separately
	neg := val.IsNegative() && !val.IsZero()
	absVal := val.Abs()

	// Split picture at '.'
	dotIdx := strings.Index(picture, ".")
	var intPic, fracPic string
	if dotIdx >= 0 {
		intPic = picture[:dotIdx]
		fracPic = picture[dotIdx+1:]
	} else {
		intPic = picture
		fracPic = ""
	}

	// Count placeholders in int part (Z/9)
	intPlaceCount := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intPlaceCount++
		}
	}
	fracPlaceCount := 0
	for _, c := range fracPic {
		if c == 'Z' || c == '9' {
			fracPlaceCount++
		}
	}

	// Format absolute value to have exactly fracPlaceCount decimal places
	// Use StringFixed to get decimal representation
	var fracDigits string
	var intDigits string

	if fracPlaceCount > 0 {
		fixed := absVal.StringFixed(int32(fracPlaceCount))
		parts := strings.SplitN(fixed, ".", 2)
		intDigits = parts[0]
		if len(parts) > 1 {
			fracDigits = parts[1]
		} else {
			fracDigits = strings.Repeat("0", fracPlaceCount)
		}
		// pad fracDigits to length
		if len(fracDigits) < fracPlaceCount {
			fracDigits = fracDigits + strings.Repeat("0", fracPlaceCount-len(fracDigits))
		} else if len(fracDigits) > fracPlaceCount {
			fracDigits = fracDigits[:fracPlaceCount]
		}
		// handle negative zero? intDigits may have '-'
	} else {
		fixed := absVal.StringFixed(0)
		intDigits = fixed
		// remove sign if any (abs already positive, but just in case)
		if strings.HasPrefix(intDigits, "-") {
			intDigits = intDigits[1:]
		}
	}
	// intDigits from abs, ensure no sign
	if strings.HasPrefix(intDigits, "-") {
		intDigits = intDigits[1:]
	}
	if strings.HasPrefix(intDigits, "+") {
		intDigits = intDigits[1:]
	}
	// remove possible leading spaces?
	intDigits = strings.TrimSpace(intDigits)
	if intDigits == "" {
		intDigits = "0"
	}
	// High-order truncation / padding to intPlaceCount
	if len(intDigits) > intPlaceCount {
		intDigits = intDigits[len(intDigits)-intPlaceCount:]
	} else if len(intDigits) < intPlaceCount {
		intDigits = strings.Repeat("0", intPlaceCount-len(intDigits)) + intDigits
	}

	// Build result
	picRunes := []rune(picture)
	res := make([]rune, len(picRunes))
	// we need indexes for intDigits and fracDigits
	intIdx := 0
	fracIdx := 0
	suppression := true

	for i, ch := range picRunes {
		switch ch {
		case 'Z', '9':
			// determine if this placeholder is before or after dot
			if dotIdx >= 0 && i > dotIdx {
				// fractional part
				if fracIdx < len(fracDigits) {
					res[i] = rune(fracDigits[fracIdx])
					fracIdx++
				} else {
					res[i] = '0'
				}
			} else {
				// integer part (including case no dot)
				var d byte
				if intIdx < len(intDigits) {
					d = intDigits[intIdx]
					intIdx++
				} else {
					d = '0'
				}
				if suppression {
					if ch == 'Z' && d == '0' {
						res[i] = ' '
						// suppression stays true
					} else if ch == '9' {
						res[i] = rune(d)
						suppression = false
					} else {
						// Z with non-zero
						res[i] = rune(d)
						suppression = false
					}
				} else {
					res[i] = rune(d)
				}
			}
		case ',':
			if suppression {
				res[i] = ' '
			} else {
				res[i] = ','
			}
		case '.':
			res[i] = '.'
		case '-':
			if neg {
				res[i] = '-'
			} else {
				res[i] = ' '
			}
		default:
			res[i] = ch
		}
	}
	return string(res)
}

func moveAmtToEd() {
	WsAmtEd = formatEdited(ledgerRec.BrAmt, "ZZ,ZZ9.99")
}
func moveBalToEd() {
	WsBalEd = formatEdited(WsBal, "-Z,ZZZ,ZZ9.99")
}
func moveTotToEdFromBranch() {
	WsTotEd = formatEdited(WsBranchTot, "-ZZZ,ZZZ,ZZ9.99")
}
func moveTotToEdFromGrand() {
	WsTotEd = formatEdited(WsGrandTot, "-ZZZ,ZZZ,ZZ9.99")
}

// Paragraphs

func ReadPara() {
	if inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++
	// pad/truncate to 14
	if len(line) < 14 {
		line = line + strings.Repeat(" ", 14-len(line))
	} else if len(line) > 14 {
		line = line[:14]
	}
	ledgerRec.BrBranch = line[0:2]
	ledgerRec.BrAcct = line[2:6]
	ledgerRec.BrType = line[6:7]
	amtStr := line[7:14]
	amtStr = strings.TrimSpace(amtStr)
	var amt decimal.Decimal
	if amtStr == "" {
		amt = decimal.NewFromInt(0)
	} else {
		// amtStr should be 7 digits, may contain spaces? keep only digits and sign?
		// Keep digits, allow negative sign just in case
		// Remove any non-digit
		// But we treat as integer string of digits
		s := strings.TrimSpace(amtStr)
		if s == "" {
			amt = decimal.NewFromInt(0)
		} else {
			// parse as integer
			// handle possibly with sign
			neg := false
			if strings.HasPrefix(s, "-") {
				neg = true
				s = s[1:]
			} else if strings.HasPrefix(s, "+") {
				s = s[1:]
			}
			// remove any non-digit
			filtered := ""
			for _, c := range s {
				if c >= '0' && c <= '9' {
					filtered += string(c)
				}
			}
			if filtered == "" {
				amt = decimal.NewFromInt(0)
			} else {
				n := decimal.RequireFromString(filtered)
				// Build decimal with exponent -2
				// Equivalent to n * 10^-2
				amt = decimal.New(n.IntPart(), -2)
				if neg {
					amt = amt.Neg()
				}
			}
		}
	}
	ledgerRec.BrAmt = amt
}

func PostPara() {
	moveAmtToEd()
	switch ledgerRec.BrType {
	case "D":
		WsBal = WsBal.Add(ledgerRec.BrAmt)
		fmt.Printf("%s D %s\n", ledgerRec.BrAcct, WsAmtEd)
	case "C":
		WsBal = WsBal.Sub(ledgerRec.BrAmt)
		fmt.Printf("%s C %s\n", ledgerRec.BrAcct, WsAmtEd)
	default:
		WsSkipped++
		fmt.Printf("%s ? SKIPPED\n", ledgerRec.BrAcct)
	}
}

func AcctBreakPara() {
	moveBalToEd()
	fmt.Printf("  ACCOUNT %s BALANCE:%s\n", WsPrevAcct, WsBalEd)
	WsBranchTot = WsBranchTot.Add(WsBal)
	WsBal = decimal.NewFromInt(0)
}

func BranchBreakPara() {
	moveTotToEdFromBranch()
	fmt.Printf(" BRANCH %s TOTAL:%s\n", WsPrevBranch, WsTotEd)
	WsGrandTot = WsGrandTot.Add(WsBranchTot)
	WsBranchTot = decimal.NewFromInt(0)
}

func GrandPara() {
	moveTotToEdFromGrand()
	fmt.Printf("GRAND TOTAL:%s\n", WsTotEd)
	// PIC 99 zero padded 2 digits
	fmt.Printf("SKIPPED: %02d\n", WsSkipped)
}

func ProcessPara() {
	if isFirstRecord() {
		WsPrevBranch = ledgerRec.BrBranch
		WsPrevAcct = ledgerRec.BrAcct
		WsFirstFlag = "N"
	} else {
		if ledgerRec.BrBranch != WsPrevBranch {
			AcctBreakPara()
			BranchBreakPara()
			WsPrevBranch = ledgerRec.BrBranch
			WsPrevAcct = ledgerRec.BrAcct
		} else {
			if ledgerRec.BrAcct != WsPrevAcct {
				AcctBreakPara()
				WsPrevAcct = ledgerRec.BrAcct
			}
		}
	}
	PostPara()
	ReadPara()
}

func MainPara() {
	// Open and read input.dat
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not exists, treat as empty
		inputLines = []string{}
	} else {
		scanner := bufio.NewScanner(f)
		// increase buffer for long lines
		buf := make([]byte, 0, 64*1024)
		scanner.Buffer(buf, 10*1024*1024)
		for scanner.Scan() {
			line := scanner.Text()
			inputLines = append(inputLines, line)
		}
		f.Close()
	}
	WsEofFlag = "N"
	WsFirstFlag = "Y"
	WsPrevBranch = "  "
	WsPrevAcct = "    "
	WsBal = decimal.NewFromInt(0)
	WsBranchTot = decimal.NewFromInt(0)
	WsGrandTot = decimal.NewFromInt(0)
	WsSkipped = 0

	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	if !isFirstRecord() {
		AcctBreakPara()
		BranchBreakPara()
	}
	GrandPara()
}

func main() {
	MainPara()
}
